26	/*! Index Threads
27	 *  Index ThreadPool maintains multiple threads resources to execute the tasks
28	 *  concurrently
29	 */
30	class IndexThreads {
31	 public:
32	  using Pointer = std::shared_ptr<IndexThreads>;
33	
34	  /*! Threads Task Group
35	   *  Manage of a group of sub-tasks which can be seen as a big task,
36	   *  so we can wait all sub-tasks finished, or get the status of them
37	   */
38	  class TaskGroup {
39	   public:
40	    using Pointer = std::shared_ptr<TaskGroup>;
41	
42	    //! Destructor
43	    virtual ~TaskGroup() = default;
44	
45	    //! Submit a task to be executed asynchronous
46	    virtual void submit(ailego::ClosureHandler &&task) = 0;
47	
48	    //! Check if the group is finished
49	    virtual bool is_finished() const = 0;
50	
51	    //! Wait until all tasks in group finished
52	    virtual void wait_finish() = 0;
53	  };
54	
55	  //! Destructor
56	  virtual ~IndexThreads() = default;
57	
58	  //! Retrieve thread count in pool
59	  virtual size_t count() const = 0;
60	
61	  //! Stop all threads
62	  virtual void stop() = 0;
63	
64	  //! Submit a task to be executed asynchronous
65	  virtual void submit(ailego::ClosureHandler &&task) = 0;
66	
67	  //! Make a task group
68	  virtual TaskGroup::Pointer make_group() = 0;
69	
70	  //! Get the current work thread index
71	  virtual int indexof_this() const = 0;
72	};
73	
74	/*! Single Queue Index Threads
75	 */
76	class SingleQueueIndexThreads : public IndexThreads {
77	 public:
78	  /*! Single Queue Index Threads Task Group
79	   */
80	  class SingleQueueTaskGroup : public TaskGroup {
81	   public:
82	    using Pointer = std::shared_ptr<SingleQueueTaskGroup>;
83	
84	    //! Constructor
85	    explicit SingleQueueTaskGroup(
86	        ailego::ThreadPool::TaskGroup::Pointer task_group)
87	        : task_group_(std::move(task_group)) {}
88	
89	    //! Submit a task to be executed asynchronous
90	    void submit(ailego::ClosureHandler &&task) override {
91	      while (task_group_->pending_count() >= kMaxQueueSize) {
92	        std::this_thread::sleep_for(std::chrono::milliseconds(1));
93	      }
94	      task_group_->enqueue_and_wake(std::move(task));
95	    }
96	
97	    //! Check if the group is finished
98	    bool is_finished() const override {
99	      return task_group_->is_finished();
100	    }
101	
102	    //! Wait until all tasks in group finished
103	    void wait_finish() override {
104	      return task_group_->wait_finish();
105	    }
106	
107	   private:
108	    //! Members
109	    ailego::ThreadPool::TaskGroup::Pointer task_group_{};
110	  };
111	
112	  //! Constructor
113	  SingleQueueIndexThreads(uint32_t size, bool binding)
114	      : pool_(
115	            size > 0 ? size : std::max(std::thread::hardware_concurrency(), 1u),
116	            binding) {}
117	
118	  //! Constructor
119	  explicit SingleQueueIndexThreads(bool binding)
120	      : SingleQueueIndexThreads(0, binding) {}
121	
122	  //! Constructor
123	  SingleQueueIndexThreads() : SingleQueueIndexThreads{false} {}
124	
125	  //! Destructor
126	  ~SingleQueueIndexThreads() override = default;
127	
128	  //! Retrieve thread count in pool
129	  size_t count() const override {
130	    return pool_.count();
131	  }
132	
133	  //! Stop all threads
134	  void stop() override {
135	    pool_.stop();
136	  }
137	
138	  //! Submit a task to be executed asynchronous
139	  void submit(ailego::ClosureHandler &&task) override {
140	    while (pool_.pending_count() >= kMaxQueueSize) {
141	      std::this_thread::sleep_for(std::chrono::milliseconds(1));
142	    }
143	    pool_.enqueue_and_wake(std::move(task));
144	  }
145	
146	  //! Make a task group
147	  TaskGroup::Pointer make_group() override {
148	    return std::make_shared<SingleQueueTaskGroup>(pool_.make_group());
149	  }
150	
151	  //! Get the current work thread index
152	  int indexof_this() const override {
153	    return pool_.indexof_this();
154	  }
155	
156	 public:
157	  //! Disable them
158	  SingleQueueIndexThreads(const SingleQueueIndexThreads &) = delete;
159	  SingleQueueIndexThreads(SingleQueueIndexThreads &&) = delete;
160	  SingleQueueIndexThreads &operator=(const SingleQueueIndexThreads &) = delete;
161	
162	 private:
163	  static constexpr size_t kMaxQueueSize = 4096u;
164	
165	  //! Members
166	  ailego::ThreadPool pool_{};
167	};
