169	/*! Borrowed Single Queue Index Threads
170	 *
171	 *  Adapts an existing thread pool to IndexThreads. The caller must keep the
172	 *  pool alive for the lifetime of this object.
173	 */
174	class BorrowedSingleQueueIndexThreads : public IndexThreads {
175	 public:
176	  //! Constructor
177	  explicit BorrowedSingleQueueIndexThreads(ailego::ThreadPool &pool)
178	      : pool_(pool) {}
179	
180	  //! Destructor
